def algorithm(func, dim, lb, ub, budget, rng):
    best_x = np.full(dim, 0.5 * (lb + ub))
    best_y = func(best_x)

    for _ in range(budget):
        x = np.clip(np.random.uniform(lb, ub, size=dim), a_min=lb, a_max=ub)
        y = func(x)

        if y < best_y:
            best_y = y
            best_x = x

    return best_x
